import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Layout from "../components/Layout";
import { getUserFromToken } from "../utils/auth";
import { deleteStudent } from "../utils/api";

const AdminStudentProfile = () => {
  const [student, setStudent] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
    }
    const user = getUserFromToken(token);
    if (user.role !== "admin") {
      navigate("/login");
    }
    const studentId = window.location.pathname.split("/")[3];
    const getStudent = async () => {
      const students = await (await fetch("/api/studentprofile")).json();
      const student = students.find(s => s.id === studentId);
      if (!student) {
        navigate("/admin-dashboard");
      }
      setStudent(student);
    };
    getStudent();
  }, [navigate]);

  const handleDelete = async () => {
    const response = await deleteStudent(student.id);
    if (response.ok) {
      navigate("/admin-dashboard");
    }
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-6 py-4">
        <h1 className="text-3xl font-bold">Student Profile</h1>
        {student && (
          <div className="bg-white shadow p-6">
            <div className="flex items-center">
              <div className="flex-1">
                <h2 className="text-2xl font-bold">Name: {student.studentName}</h2>
                <p className="text-gray-600">Student Number: {student.studentNumber}</p>
              </div>
              <div className="flex items-center">
                <button
                  className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded"
                  onClick={handleDelete}
                >
                  Delete Student
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default AdminStudentProfile;
